import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

function invalid(message) {
  throw new Error(message);
}

function validateSections(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    invalid('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    invalid('sections must be an array');
  }

  const ids = new Set();
  const entries = [];
  for (let index = 0; index < sections.length; index += 1) {
    if (!(index in sections)) invalid('sections must be dense');
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      invalid('each section must be a non-array object');
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0) invalid('section id must be a nonempty string');
    if (typeof text !== 'string') invalid('section text must be a string');
    if (!Number.isSafeInteger(priority) || priority < 0) {
      invalid('section priority must be a nonnegative safe integer');
    }
    if (typeof required !== 'boolean') invalid('section required must be a boolean');
    if (ids.has(id)) invalid('section ids must be unique');
    ids.add(id);
    const frame = '### ' + JSON.stringify(id) + '\n' + text + '\n';
    entries.push({ id, required, priority, index, frame, cost: Buffer.byteLength(frame, 'utf8') });
  }
  return entries;
}

export function packContext(sections, maxBytes) {
  const entries = validateSections(sections, maxBytes);
  const included = [];
  const omitted = [];
  const frames = [];
  let bytes = 0;

  for (const entry of entries) {
    if (entry.required) {
      if (entry.cost > maxBytes - bytes) {
        invalid('required sections exceed maxBytes');
      }
      frames.push(entry.frame);
      included.push(entry.id);
      bytes += entry.cost;
    }
  }

  const optional = entries.filter((entry) => !entry.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);
  const selected = new Set();
  for (const entry of optional) {
    if (entry.cost <= maxBytes - bytes) {
      frames.push(entry.frame);
      included.push(entry.id);
      selected.add(entry.index);
      bytes += entry.cost;
    }
  }
  for (const entry of entries) {
    if (!entry.required && !selected.has(entry.index)) omitted.push(entry.id);
  }

  return { text: frames.join(''), bytes, included, omitted };
}

function runCli() {
  if (process.argv.length !== 3) invalid('expected exactly one input JSON file');
  const input = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  const result = packContext(input.sections, input.maxBytes);
  process.stdout.write(JSON.stringify(result) + '\n');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    runCli();
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

